from common import *
B='025影子.txt'
make('xu_xin','许信',B,
'许信是卫斯理学生时代的好友，继承堂叔废弃的大屋后，与朋友带着冒险和寻宝的兴奋入住。他会说笑、争辩，也会因无法理解的影子吓得失色；嘴上故作大胆与真实恐惧之间的差距，构成早期行动的节奏。毛雪屏愿买下屋子后，他又一度猜想影子是能满足任何愿望的宝物，后来明确承认这种想法幼稚。他取钱离乡，在泰国古庙长期居住，逐渐远离城市，直到得到另一个影子样个体，才重新寻找卫斯理。他自称当年离开的决定仿佛受外力影响，这只是自身感受，不能证明已经被影子控制。多年后的许信不再只想获利，而把影子视作一个生命，拒绝把它交给研究机构当对象，主张先给予陌生生命友谊。他也有矛盾的一面：因争执激动而把石球重顿在桌上，使其崩下一片并发出异声。最终他邀朋友赴庙共住多年探索沟通，自己先行返回；古庙随后失火，他不知所终，没有尸体证实死亡。综合卡保留热情转向执著的过程，友谊、退隐与求知互相拉扯，不能让他自动掌握影子来历或获得朋友的调查装备。',
'返回泰国古庙后庙宇失火，本人失踪，死亡未证实。','长期观察与异种友谊尝试','凭多年居庙观察和石球保管接近第二个影子，提出平面生命与小星体假说。','假说未被证实，不能命令影子实现愿望或确认精神沟通；急躁会危及石球，后续物品状态未知。',[(12,19,'早期友情'),(1169,1202,'宝物猜想与离乡'),(1397,1425,'长期居庙及不同影子'),(1543,1604,'友谊立场、争执和邀约'),(1635,1643,'火灾与失踪')],
'把陌生存在当作可交往的生命，同时寻找值得长期投入的生活。',[('朋友只想把影子送检','自己认为对方需要友谊','争论研究方式并要求尊重对象，避免以愤怒伤害其容器。'),('旧友情与长期目标冲突','对方不愿放弃城市生活','表达失望并允许对方拒绝，不把陪伴当义务。'),('出现似是而非的超常解释','证据仍只是观察','区分信念与事实，不再许诺愿望成真。')],scores=(1,0,1,2,1,1),tier='并',deploy='采用失踪前最后可行动形态；火灾后生死与石球去向未知，参战不补造原作逃生。')
make('mao_xueping','毛雪屏',B,
'毛雪屏是一所大学历史系主任和考古研究者，关心古代遗物中难以解释的现象，也研究被人归为降头术的传统。他曾在泰国古庙住过一段时间，亲眼见老和尚打开石球，放出可在墙上活动的影子，并用手势与之交流。这种经历使他不满足于把异常全当迷信，也没有因此掌握传闻里的全部法术。老和尚去世、物件被买走后，他沿捐簿查到许姓实业家，多次来访，却只见废弃住宅。终于遇到卫斯理并再次见到影子，他愿付出积蓄的大部分买下屋子，要求两个年轻人不要再来，也不要向外传播。独占研究环境的急切使他在交易后很快赶客，和先前礼貌说明的样子形成反差。老锁匠后来为他修理装石球的木箱，看到他似乎拥有两个影子，触碰石球时又发生惊慌。几天后房屋大火，毛教授不再出现，救火者没有找到尸体；起火原因、本人是否死亡，以及影子是否还在，都无定论。终局卡采用最后自主研究的形态，保留他愿为谜团付出生活资源的执著，也应让他理解封闭与缺少见证会使知识随失踪一起消散。',
'买屋后与第一影子共同活动；住宅失火后下落未知，未见尸体。','考古追索与异常物件观察','结合旧物来源、寺庙捐簿及目击追查石球，愿提供长期研究环境。','研究降头不等于拥有降头能力；只能转述和尚交流经验，未证实他能完全支配影子。',[(1027,1063,'学术身份'),(1071,1108,'目击与追查物件'),(1133,1162,'交易和排他保密'),(1269,1304,'修箱、火灾及未解原因')],
'追索常规解释之外的古物与生命，愿付高昂代价获得近距离观察。',[('遇到被视为迷信的现象','存在可追溯的物件与目击','核对来源并亲自观察，不先把传说全部当真。'),('取得难得研究机会','担心外人干扰','倾向要求保密，终局经验也会促使他保存独立记录。'),('别人触碰关键容器','可能惊动未知存在','先阻止随意操作，再解释风险而非仅驱赶。')],scores=(1,0,1,2,1,1),tier='并',deploy='采用住宅火灾前最后可行动研究者形态；火后失踪不强写成死亡或逃生。')
make('shadow_house','古庙的幽灵／大屋影子',B,
'这个被称为古庙幽灵的影子样存在，最早的可靠关联来自毛雪屏的回忆：它在泰国老和尚保管的石球中出现，像人形黑影一样伸展，能对手势作出反应，并被老和尚当作朋友。物件后来被许姓实业家买走，影子随之进入大屋；主人无法忍受它参与生活，试图把它锁进钢柜抽屉并弃屋。多年后，卫斯理亲眼看见人形黑影从极窄的抽屉缝慢慢挤出，摇头、停留，仿佛在观察惊恐的人。铜镇纸砸向它时只撞到钢柜，影子随后缩回；这可证明该次接触没有像击中实体人体，却不足以推定免疫所有物理作用。它后来沿墙缓慢下楼，向毛教授招手，又返回楼上，行为并非持续攻击。老锁匠触石球时感觉影子扑来，属于受惊后的叙述，没有造成明确伤害。毛教授购屋后与它接近，房屋却失火，人和影子均不再出现，原因不明。角色卡把它作为有疑似沟通行为的未知个体保存，真正生命形式、是否纯二维、是否会思考乃至火灾关系都保留问号，不赋予纵火、附体或实现愿望的权柄。',
'毛教授住宅失火后未再被见到，生死及石球状态未知。','贴面移动、形态伸缩与手势回应','在墙面、柜面上呈人形黑影，可从窄缝移出并作类似招手、摇头的动作；与石球有稳定关联。','无已证实的愿望实现、精神控制或火焰能力；平面生命只是解释，不能推成所有攻击无效。',[(1074,1093,'石球与和尚交流'),(704,712,'主人弃屋记述'),(751,805,'挤缝与镇纸接触'),(1121,1136,'沿墙和招手'),(1273,1304,'触球、火灾和疑问')],
'尝试靠近与交流，在他人的恐惧和自身未知需求之间寻找空间。',[('人类对靠近表现强烈惊慌','没有明确攻击目的','减慢动作或退回熟悉表面，以可观察的手势回应。'),('关联石球被陌生者触碰','无法判断对方意图','靠近示意但不自动造成无证据伤害。'),('被要求完成神灯般愿望','缺乏任何原文机制','不执行超出已知动作的奇迹，保持未知而有限的交流。')],roles=('单书主角','阶段性对立的未知个体'),aliases=('第一影子',),scores=(1,1,1,3,1,1),tier='并',appearance='没有实体投影来源的人形黑影，能伸缩并贴着墙面或柜面移动。',destruction='没有确认的致命攻击或破坏输出。',durability='一次镇纸攻击未击中实体；对热、光、容器破坏等抗性未知。',speed='可缓慢沿墙移动和从狭缝伸出，没有高速战斗证据。',energy='未示能量攻击；异声与形态变化不能算破坏能量。',stamina='曾在屋中存在多年，与石球关系密切，活动条件未完全解释。',intelligence={'in_combat':'遭镇纸投掷后缩回，未展示战术攻击。','knowledge':'可能理解手势，具体知识未知。','planning':'不能据似人动作杜撰复杂目的。','adaptation':'能面对不同人作手势与位置调整。'},confidence='medium',uncertainties=('是否生物、二维存在或某种投影，没有定论。','与火灾的因果未证实。'))
make('shadow_xuxin','许信带来的第二影子',B,
'这个影子由许信在泰国古庙长期居住后得到，原文明说它不是少年时大屋里的那个，只是许信相信属于同类。农民说在流星飞过后发现石球，球外曾有云状物消散；这是一条来源叙述，不能证明个体能自行制造宇宙或任意星际旅行。卫斯理重逢许信时，亲眼看见粗糙石球分成两半，其中方形空腔的黑影扩展为人形，移到墙上，又挪到窗外，仿佛观看街景。它沿房间、浴室和地毯游移，最后缩小到黑点般进入石球，许信说这种回归常在短时间外出后发生。许信把它当作需要友谊的生命，反对将它送去做实验；影子没有直接用语言确认这一立场。争执中石球被顿坏一角，里面发出类似呻吟的声音，使关联容器的完整性成为应谨慎对待的限制。石片分析只见常见元素与逸散气体，没有验证小星体孕育单一生命的推断。许信带它返庙后发生火灾，两者都失踪。终局参战应采用最后可观察的石球关联形态，不附加第一影子的全部经历、和尚的沟通成果或未证实的诱导人心能力。',
'随许信回庙后遇到寺庙火灾，未再出现，存亡未知。','表面游移、尺度变化与石球回归','可由石球空腔扩展成人形影子，在相连表面移动，短时后缩小返回。','不具已验证的完全二维无敌性；石球破损与异常声有实证关联，外出时长上限未知。不会因同类推测继承另一影子全部表现。',[(1421,1425,'明确为另一个个体'),(1434,1468,'石球和显形'),(1489,1491,'移向窗外'),(1537,1544,'游移与回归'),(1569,1575,'容器破损和异声'),(1619,1643,'材质检查及火灾失踪')],
'在陌生环境中活动并回到关联石球，能否发展进一步交流保持开放。',[('外界出现新场景','石球所在环境暂时稳定','以有限表面移动观察，随后回归。'),('容器受到撞击','出现破损或震动','表现退缩与异常声，不能当作无限可消耗外壳。'),('旁人投射复杂动机','没有可理解的共同语言','用有限动作回应，不自动说出他人的期待。')],roles=('单书主角','未知生命个体'),aliases=('第二影子',),scores=(0,1,1,2,1,1),tier='并',appearance='从灰色石球中扩展的人形黑影，可缩成极小黑点。',destruction='未显示破坏或伤人能力。',durability='本体抗性不明；关联石球会掉落碎片并引起异声。',speed='沿墙、窗面、地毯和桌面移动，无量化极速。',energy='无已确认能量投射。',stamina='外出不久会回到石球，持续行动受未明条件限制。',intelligence={'in_combat':'没有主动战斗实例。','knowledge':'无法从外形直接确定知识或语言。','planning':'回到石球体现稳定行为，但目的解释仍有限。','adaptation':'能探索新室内环境并调整大小。'},uncertainties=('许信的小星体和单一生命理论未被证实。','火灾原因及是否死亡未明。'))
cov(B,[('小郭','weisili_xiao_guo','跨书重要配角','帮助许信联络卫斯理。'),('许信','xu_xin','单书主角','从少年冒险者到长期照护研究者。'),('毛雪屏','mao_xueping','单书主角','追索并买屋接近第一影子。'),('大屋影子','shadow_house','未知主角','少年事件与毛教授关系核心。'),('第二影子','shadow_xuxin','未知主角','多年后许信带来的不同个体。')],[('老锁匠、阿尚、许氏夫妇','开锁、财产旧事和后续证言的重要单次辅助，未形成独立主角或反派线。'),('古庙老和尚及新主持','来源与交流的前史辅助；降头能力只有泛述，不杜撰术法卡。'),('农民、实验所人员、末尾科学家及传话职员','来源、检验或传讯的单次辅助，未确立独立角色弧。')],['第一和第二影子明确分卡；两个火灾均原因未知，不用相似性推定影子纵火。'])
